import{_ as l,l as i,o as e,c as n,v as t,p as s,x as o,d as E,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"全局优化在校准","description":"","frontmatter":{"title":"全局优化在校准","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/calibration-global-opt.md","filePath":"quant/calibration-global-opt.md","lastUpdated":1789023840000}'),A={name:"quant/calibration-global-opt.md"};function h(u,a,c,B,m,_){const r=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="全局优化在校准" tabindex="-1">全局优化在校准 <a class="header-anchor" href="#全局优化在校准" aria-label="Permalink to &quot;全局优化在校准&quot;">​</a></h1><div class="epigraph"><p>Heston 与 SABR 的误差曲面有多个局部谷；从昨日参数出发的局部牛顿，可能停在错误的谷里还自以为拟合良好。</p><footer>—— 对照 Heston 与 SABR 校准实践；全局搜索见 Differential Evolution 等在参数校准中的应用</footer></div><p><a href="/quant/calibration-regularization">上一课</a>加了罚项，目标函数仍可能<strong>非凸</strong>。本课缺口是优化器：局部 Gauss–Newton / Levenberg–Marquardt 依赖初值；Heston 的 \\(Feller\\) 边界、SABR 的 \\(\\rho,\\nu\\) 会造出多峰。后课报价惯例把校准输入的坐标系换掉；这里先写搜索策略，不把全局优化写成万能。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>同一张香草，从两组初值出发得到两组 \\((\\kappa,\\theta,\\nu,\\rho,v_0)\\)，价格 RMSE 都可接受，但远期微笑与 cliquet 价格不同。这是模型风险在校准算法里的实现：你连「官方 \\(\\theta\\)」都没选唯一。问题是把全局搜索当<strong>日频的粗定位</strong>，把带正则的局部牛顿当<strong>盘中的精炼</strong>，并拒绝「RMSE 更小 0.1 个波动点」但参数跳到另一谷的解——除非隔日罚允许。</p><p>Feller 条件 \\(2\\kappa\\theta\\gt \\nu^2\\) 在 <a href="/quant/heston-feller">Heston–Feller</a> 已写。优化器若穿过边界，特征函数数值与矩都会变，看起来像又一个局部谷，其实是数值坏点。约束应硬编码，不是靠罚一点了事。</p><h3 id="全局不等于随机碰运气" tabindex="-1">全局不等于随机碰运气 <a class="header-anchor" href="#全局不等于随机碰运气" aria-label="Permalink to &quot;全局不等于随机碰运气&quot;">​</a></h3><p>Differential Evolution、粒子群、多起点牛顿，都要把随机种子、种群、预算记进校准日志。不可复现的「今天搜到更优」不能进生产。预算应花在：多起点覆盖参数盒、用 AAD 加速每个起点的局部精炼，而不是无限代进化。</p><p><span class="marginnote">校准的目标是稳定对冲，不是学术上的全局最小。全局最小若在翼部过拟合，正则化课已经要求丢掉它。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>参数盒：来自昨日、来自历史分位、来自无套利（\\(\\nu\\gt 0\\)，\\(|\\rho|\\lt 1\\)）。多起点：昨日解 + 盒上的拉丁超立方。每个起点做带 \\(\\lambda R\\) 的 LM。若多个谷的目标值在价差容差内，选隔日距离最小者。真正的大跳（体制切换）用人工确认或第二模型对照，不要让 DE 在夜盘安静改写官方参数。</p><p>SABR 按到期分别校准再插值，比一个全局 SABR 扫所有期限更少多峰，但会失去期限一致，见 <a href="/quant/ssvi-term-consistency">SSVI 期限</a>。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>似然/误差作为 \\(\\theta\\) 的函数，因价格对参数非线性而多峰。特征函数振荡、积分截断又叠加数值多峰。全局搜索探索的是这条粗糙曲面；局部牛顿在二次近似成立的谷底才快。生产把两者分层，是承认计算预算与稳定性，而不是承认「市场有多个真实参数」。</p>',14)),(e(),s(p,null,{default:o(()=>[d(r,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20Box%5B%22%E5%8F%82%E6%95%B0%E7%9B%92%E4%B8%8E%E7%A1%AC%E7%BA%A6%E6%9D%9F%22%5D%20--%3E%20Multi%5B%22%E5%A4%9A%E8%B5%B7%E7%82%B9%22%5D%0A%20%20Yest%5B%22%E6%98%A8%E6%97%A5%E8%A7%A3%22%5D%20--%3E%20Multi%0A%20%20Multi%20--%3E%20Loc%5B%22%E5%B8%A6%E6%AD%A3%E5%88%99%E7%9A%84%E5%B1%80%E9%83%A8%E7%89%9B%E9%A1%BF%22%5D%0A%20%20Loc%20--%3E%20Pick%5B%22%E4%BB%B7%E5%B7%AE%E5%AE%B9%E5%B7%AE%E5%86%85%E9%80%89%E9%9A%94%E6%97%A5%E6%9C%80%E8%BF%91%22%5D%0A%20%20Pick%20--%3E%20Log%5B%22%E6%97%A5%E5%BF%97%20%E7%A7%8D%E5%AD%90%20%E9%A2%84%E7%AE%97%20%E5%8F%AF%E5%A4%8D%E7%8E%B0%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>维度一高（混合局部-随机波动、LMM 的整条 vol 曲线），全局搜索指数爆炸，应降维：先校准边际再校准相关，或用 PCA 因子当参数。全局最优的统计误差条本身就宽，报告应带「等价谷」列表。不要用无法复现的黑盒优化器当审计对象。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>随机波动校准非凸；RMSE 接近的谷可以对冲比完全不同。</li><li>多起点 + 隔日选择，全局搜索只做粗定位且必须可复现。</li><li>硬约束挡住数值坏点；全局最小仍要过正则化关。</li><li>出处：Heston, <em>RFS</em>, 1993；Hagan et al., SABR, <em>Wilmott</em>, 2002；差分进化见 Storn and Price, <em>Journal of Global Optimization</em>, 1997。</li></ul>',4))])}const q=l(A,[["render",h]]);export{b as __pageData,q as default};
